import type { MetadataRoute } from "next"
import { absoluteUrl } from "@/lib/seo"

const publicRoutes = [
  { path: "/", priority: 1 },
  { path: "/bai-viet", priority: 0.8 },
  { path: "/ve-chung-toi", priority: 0.7 },
  { path: "/huong-dan-su-dung", priority: 0.7 },
  { path: "/lien-he", priority: 0.6 },
] as const

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date()

  return publicRoutes.map((route) => ({
    url: absoluteUrl(route.path),
    lastModified: now,
    changeFrequency: route.path === "/bai-viet" ? "daily" : "weekly",
    priority: route.priority,
  }))
}

src/components/shared/cart-drawer.tsx.content:
"use client";

import Link from "next/link";
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@ui/components/drawer";
import { Button } from "@ui/components/button";
import { Badge } from "@ui/components/badge";
import {
  Minus,
  Package2,
  Plus,
  ShoppingCart,
  Trash2,
  X,
  Gift,
} from "lucide-react";
import { useCart } from "@/hooks/use-cart";
import { formatVND } from "@/lib/format";
import { cn } from "@ui/lib/utils";
import { getActiveGiftRuleForUnit } from "@/lib/gift-rules-from-fulfillment-note";

type CartDrawerContextValue = {
  openCart: () => void;
  closeCart: () => void;
};

const CartDrawerContext = createContext<CartDrawerContextValue | null>(null);

export function useOpenCartDrawer(): () => void {
  const ctx = useContext(CartDrawerContext);
  if (!ctx) {
    throw new Error("useOpenCartDrawer must be used within CartDrawerHost");
  }
  return ctx.openCart;
}

function CartDrawerPanel({ onNavigate }: { onNavigate: () => void }) {
  const {
    lines,
    unitCount,
    subtotal,
    promoDiscount,
    grandTotal,
    setQuantity,
    remove,
    clear,
  } = useCart();
  const isEmpty = lines.length === 0;

  return (
    <DrawerContent className="flex h-full max-h-svh w-full max-w-md flex-col border-l border-outline-variant p-0 data-[vaul-drawer-direction=right]:w-full data-[vaul-drawer-direction=right]:max-w-md data-[vaul-drawer-direction=right]:sm:max-w-md">
      <DrawerHeader className="flex flex-row items-center justify-between space-y-0 border-b border-outline-variant px-6 py-5">
        <div>
          <DrawerTitle className="flex items-center gap-2 text-xl font-extrabold">
            <ShoppingCart className="size-5 text-primary" aria-hidden />
            Giỏ hàng
          </DrawerTitle>
          <DrawerDescription className="text-xs">
            {isEmpty
              ? "Chưa có sản phẩm nào"
              : `${lines.length} loại · ${unitCount} đơn vị`}
          </DrawerDescription>
        </div>
        {!isEmpty && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={clear}
            className="rounded-lg text-destructive hover:bg-destructive/10"
          >
            <X className="mr-1 size-4" aria-hidden />
            Xoá tất cả
          </Button>
        )}
      </DrawerHeader>

      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-6 py-4">
        {isEmpty && (
          <div className="space-y-3 py-16 text-center">
            <Package2 className="mx-auto size-16 text-outline-variant opacity-30" />
            <p className="text-base font-bold text-muted-foreground">
              Giỏ hàng trống
            </p>
            <p className="text-sm text-muted-foreground">
              Hãy chọn sản phẩm từ danh mục để bắt đầu mua sắm.
            </p>
            <Button
              nativeButton={false}
              render={<Link href="/catalog" onClick={onNavigate} />}
              className="mt-2 rounded-xl"
            >
              Xem danh mục
            </Button>
          </div>
        )}

        {lines.map((line) => {
          const maxQty = Math.max(
            1,
            Math.floor(line.stock / Math.max(line.qtyPerUnit, 1)),
          );
          const listUnit = line.listUnitPrice ?? line.unitPrice;
          const unitNow = line.unitPrice;
          const showListStrike = listUnit > unitNow;
          const listLineTotal = listUnit * line.quantity;
          const saleLineTotal = unitNow * line.quantity;

          const retailUnit = Math.max(0, Math.floor(listUnit));
          const promoUnitRaw = line.promoUnitPrice;
          const promoUnitFloored =
            promoUnitRaw != null &&
            Number.isFinite(promoUnitRaw) &&
            Math.floor(promoUnitRaw) > 0
              ? Math.floor(promoUnitRaw)
              : null;
          const hasPromoTier =
            promoUnitFloored != null &&
            retailUnit > 0 &&
            promoUnitFloored < retailUnit;
          const discountPct =
            hasPromoTier && retailUnit > 0
              ? Math.round(
                  ((retailUnit - promoUnitFloored!) / retailUnit) * 100,
                )
              : 0;
          const minQ = Math.max(0, Math.floor(line.minPromoQty ?? 0));
          const needMoreForKm =
            minQ > 1 && line.quantity < minQ ? minQ - line.quantity : 0;

          const giftRule = getActiveGiftRuleForUnit(
            line.fulfillmentNote,
            line.unitType,
          );
          const giftUnlocked =
            giftRule != null && line.quantity >= giftRule.minQty;

          return (
            <div
              key={`${line.productId}:${line.unitType}`}
              className="flex gap-3 rounded-2xl border border-outline-variant bg-background p-3"
            >
              <div className="flex size-16 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-outline-variant/40 bg-white">
                {line.image ? (
                  <img
                    src={line.image}
                    alt=""
                    className="h-full w-full rounded-xl object-cover"
                  />
                ) : (
                  <Package2 className="size-7 text-outline-variant" />
                )}
              </div>
              <div className="min-w-0 flex-grow">
                <p className="line-clamp-2 text-sm font-bold leading-snug">
                  {line.name}
                </p>
                <Badge className="mt-1 border-outline-variant/40 bg-muted px-1.5 py-0 text-[10px] font-semibold text-muted-foreground">
                  {line.unitLabel}
                </Badge>

                <div className="mt-2 flex flex-wrap items-end gap-1.5 sm:gap-2">
                  {showListStrike && (
                    <p className="mb-0.5 text-sm font-semibold text-muted-foreground line-through">
                      {formatVND(listUnit)}
                    </p>
                  )}
                  <p className="text-lg font-black text-primary sm:text-xl">
                    {formatVND(unitNow)}
                  </p>
                  <p className="mb-0.5 text-xs text-muted-foreground sm:text-sm">
                    / {line.unitLabel}
                  </p>
                  {line.isWholesale && (
                    <Badge
                      className={cn(
                        "mb-0.5 text-[10px] font-bold",
                        showListStrike
                          ? "border-primary/20 bg-primary/10 text-primary"
                          : "border-secondary/20 bg-secondary/10 text-secondary-foreground",
                      )}
                    >
                      {showListStrike ? "Giá KM (đủ SL)" : "Giá ban đầu"}
                    </Badge>
                  )}
                </div>

                {hasPromoTier && (
                  <div
                    className={cn(
                      "mt-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] leading-snug sm:text-xs",
                      minQ > 1
                        ? line.isWholesale
                          ? "border-emerald-500/35 bg-emerald-500/10 text-emerald-950 dark:text-emerald-100"
                          : "border-amber-500/35 bg-amber-500/10 text-amber-950 dark:text-amber-100"
                        : "border-outline-variant/50 bg-muted/50 text-muted-foreground",
                    )}
                  >
                    {minQ > 1 ? (
                      <>
                        <p className="font-medium text-foreground">
                          Điều kiện KM: từ{" "}
                          <span className="font-bold text-primary">
                            {minQ} {line.unitType}
                          </span>{" "}
                          trở lên
                          {discountPct > 0 ? (
                            <>
                              {" "}
                              — giảm ~{discountPct}% so với giá niêm yết
                            </>
                          ) : null}
                          .
                        </p>
                        <p
                          className={cn(
                            "mt-0.5",
                            line.isWholesale
                              ? "text-emerald-800 dark:text-emerald-300"
                              : "text-amber-900 dark:text-amber-200",
                          )}
                        >
                          {line.isWholesale
                            ? `Đang đủ: ${line.quantity} ${line.unitType} — áp giá KM (${formatVND(promoUnitFloored!)} / ${line.unitLabel}).`
                            : `Hiện ${line.quantity} ${line.unitType}; cần thêm ít nhất ${needMoreForKm} ${line.unitType} để áp giá KM (${formatVND(promoUnitFloored!)} / ${line.unitLabel}).`}
                        </p>
                      </>
                    ) : (
                      <p>
                        {discountPct > 0 ? (
                          <>
                            Giá KM áp dụng mọi số lượng (khoảng {discountPct}% so
                            với {formatVND(retailUnit)} / {line.unitLabel}).
                          </>
                        ) : (
                          <>
                            Giá KM áp dụng mọi số lượng —{" "}
                            {formatVND(promoUnitFloored!)} / {line.unitLabel}.
                          </>
                        )}
                      </p>
                    )}
                  </div>
                )}

                {giftRule && (
                  <div
                    className={cn(
                      "mt-1.5 rounded-lg border px-2.5 py-1.5 text-[11px] leading-snug sm:text-xs",
                      giftUnlocked
                        ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-950 dark:text-emerald-100"
                        : "border-amber-500/35 bg-amber-500/10 text-amber-950 dark:text-amber-200",
                    )}
                  >
                    <p className="flex items-center gap-1.5 font-semibold text-foreground">
                      <Gift className="size-3.5 shrink-0" aria-hidden />
                      {giftUnlocked
                        ? "Đã đủ điều kiện nhận quà"
                        : "Ưu đãi quà tặng"}
                    </p>
                    <p className="mt-0.5">
                      Từ{" "}
                      <span className="font-bold text-primary">
                        {giftRule.minQty}
                      </span>{" "}
                      {giftRule.unitType}: tặng{" "}
                      <span className="font-bold">
                        {giftRule.giftQty} {giftRule.giftName}
                      </span>
                      {giftRule.giftSku
                        ? ` (SKU: ${giftRule.giftSku})`
                        : ""}
                      {giftRule.giftUnitType
                        ? ` — đơn vị quà: ${giftRule.giftUnitType}`
                        : ""}
                      .
                    </p>
                    {!giftUnlocked && (
                      <p className="mt-0.5 text-[10px] opacity-90 sm:text-xs">
                        Cần thêm{" "}
                        <span className="font-bold">
                          {Math.max(0, giftRule.minQty - line.quantity)}
                        </span>{" "}
                        {giftRule.unitType} trong giỏ để đủ điều kiện quà.
                      </p>
                    )}
                  </div>
                )}

                <div className="mt-2 flex items-center justify-between gap-2">
                  <div className="flex h-8 items-center overflow-hidden rounded-lg border border-outline-variant bg-surface">
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 rounded-none"
                      onClick={() =>
                        setQuantity(
                          line.productId,
                          line.unitType,
                          line.quantity - 1,
                        )
                      }
                    >
                      <Minus className="size-3" />
                    </Button>
                    <span className="w-9 text-center text-sm font-bold">
                      {line.quantity}
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 rounded-none"
                      disabled={line.quantity >= maxQty}
                      onClick={() =>
                        setQuantity(
                          line.productId,
                          line.unitType,
                          line.quantity + 1,
                        )
                      }
                    >
                      <Plus className="size-3" />
                    </Button>
                  </div>
                  <div className="shrink-0 text-right">
                    {showListStrike && (
                      <p className="text-xs text-muted-foreground line-through tabular-nums">
                        {formatVND(listLineTotal)}
                      </p>
                    )}
                    <p className="text-sm font-black tabular-nums text-primary">
                      {formatVND(saleLineTotal)}
                    </p>
                  </div>
                </div>
              </div>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="size-8 shrink-0 text-destructive hover:bg-destructive/10"
                onClick={() => remove(line.productId, line.unitType)}
              >
                <Trash2 className="size-4" />
              </Button>
            </div>
          );
        })}
      </div>

      {!isEmpty && (
        <DrawerFooter className="flex-col gap-3 border-t border-outline-variant px-6 py-5 sm:flex-col">
          <div className="space-y-1.5 text-sm">
            <div className="flex justify-between text-muted-foreground">
              <span>Tạm tính</span>
              <span className="font-semibold tabular-nums text-foreground">
                {formatVND(subtotal)}
              </span>
            </div>
            {promoDiscount > 0 && (
              <div className="flex justify-between text-primary">
                <span>Mã khuyến mãi</span>
                <span className="font-semibold tabular-nums">
                  −{formatVND(promoDiscount)}
                </span>
              </div>
            )}
            <div className="flex justify-between border-t border-outline-variant/60 pt-2 text-base font-semibold">
              <span className="text-muted-foreground">Ước tính thanh toán</span>
              <span className="text-xl font-black tabular-nums text-primary">
                {formatVND(grandTotal)}
              </span>
            </div>
          </div>
          <p className="text-xs text-muted-foreground">
            Thanh toán khi nhận hàng (COD). Phí vận chuyển sẽ được tính khi xác
            nhận đơn.
          </p>
          <Button
            nativeButton={false}
            render={<Link href="/checkout" onClick={onNavigate} />}
            className="h-12 w-full rounded-xl font-bold"
          >
            Tiến hành đặt hàng
          </Button>
          <Button
            nativeButton={false}
            variant="outline"
            render={<Link href="/cart" onClick={onNavigate} />}
            className="w-full rounded-xl"
          >
            Mở trang giỏ đầy đủ
          </Button>
        </DrawerFooter>
      )}
    </DrawerContent>
  );
}

/** Bọc toàn bộ storefront cần nút mở giỏ (vd. quanh `<Header />`). */
export function CartDrawerHost({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const openCart = useCallback(() => setOpen(true), []);
  const closeCart = useCallback(() => setOpen(false), []);
  const value = useMemo(
    () => ({ openCart, closeCart }),
    [openCart, closeCart],
  );

  return (
    <CartDrawerContext.Provider value={value}>
      <Drawer
        direction="right"
        open={open}
        onOpenChange={setOpen}
        shouldScaleBackground={false}
      >
        {children}
        <CartDrawerPanel onNavigate={closeCart} />
      </Drawer>
    </CartDrawerContext.Provider>
  );
}

src/components/shared/cart-line-item.tsx.content:
"use client";

import { Button } from "@ui/components/button";
import { Badge } from "@ui/components/badge";
import { Minus, Package2, Plus, Trash2 } from "lucide-react";
import type { CartLine } from "@/hooks/use-cart";
import { formatVND } from "@/lib/format";
import { getActiveGiftRuleForUnit } from "@/lib/gift-rules-from-fulfillment-note";

export function cartLineMaxQty(line: CartLine): number {
  return Math.max(1, Math.floor(line.stock / Math.max(line.qtyPerUnit, 1)));
}

type CartLineItemProps = {
  line: CartLine;
  onQuantityChange: (quantity: number) => void;
  onRemove: () => void;
};

/** Một dòng giỏ — layout giống danh sách sản phẩm ở trang checkout (ảnh, badge đơn vị, stepper). */
export function CartLineItem({
  line,
  onQuantityChange,
  onRemove,
}: CartLineItemProps) {
  const maxQty = cartLineMaxQty(line);
  const listUnit = line.listUnitPrice ?? line.unitPrice;
  const showListStrike = listUnit > line.unitPrice;
  const giftRule = getActiveGiftRuleForUnit(
    line.fulfillmentNote,
    line.unitType,
  );
  const giftUnlocked =
    giftRule != null && line.quantity >= giftRule.minQty;

  return (
    <div className="flex flex-col items-center gap-6 p-6 transition-colors hover:bg-muted/5 sm:flex-row">
      <div className="flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-2xl border border-outline-variant/50 bg-white p-2 shadow-sm">
        {line.image ? (
          <img
            src={line.image}
            alt={line.name}
            className="w-full h-full object-cover rounded-lg"
          />
        ) : (
          <Package2 className="h-10 w-10 text-outline-variant" />
        )}
      </div>
      <div className="min-w-0 flex-grow text-center sm:text-left">
        <Badge className="mb-2 border-primary/20 bg-primary/10 px-2 py-0 text-[10px] font-bold uppercase tracking-wide text-primary">
          {line.unitLabel}
          {line.isWholesale ? " · Khuyến mãi" : " · Ban đầu"}
        </Badge>
        <h3 className="line-clamp-2 text-lg font-bold leading-tight">{line.name}</h3>
        <div className="mt-2 flex flex-wrap items-center justify-center gap-2 sm:justify-start sm:gap-3">
          {showListStrike && (
            <span className="text-sm text-muted-foreground line-through decoration-muted-foreground/80">
              {formatVND(listUnit)}
            </span>
          )}
          <span className="text-xl font-extrabold text-foreground">
            {formatVND(line.unitPrice)}
          </span>
          <span className="text-sm text-muted-foreground">
            × {line.quantity} {line.unitType}
          </span>
        </div>
        {giftRule && (
          <p
            className={`mt-2 text-xs font-medium ${
              giftUnlocked
                ? "text-emerald-700 dark:text-emerald-400"
                : "text-amber-800 dark:text-amber-300"
            }`}
          >
            {giftUnlocked ? "Đủ điều kiện quà: " : "Quà tặng: "}
            từ {giftRule.minQty} {giftRule.unitType} — {giftRule.giftQty}{" "}
            {giftRule.giftName}
            {!giftUnlocked &&
              ` (cần thêm ${Math.max(0, giftRule.minQty - line.quantity)} ${giftRule.unitType})`}
            .
          </p>
        )}
      </div>
      <div className="flex items-center gap-4">
        <div className="flex h-12 items-center overflow-hidden rounded-2xl border border-outline-variant bg-surface shadow-sm">
          <Button
            variant="ghost"
            size="icon"
            className="h-12 w-12 rounded-none"
            onClick={() => onQuantityChange(line.quantity - 1)}
          >
            <Minus className="h-4 w-4" />
          </Button>
          <span className="w-12 text-center text-lg font-extrabold">
            {line.quantity}
          </span>
          <Button
            variant="ghost"
            size="icon"
            className="h-12 w-12 rounded-none"
            disabled={line.quantity >= maxQty}
            onClick={() => onQuantityChange(line.quantity + 1)}
          >
            <Plus className="h-4 w-4" />
          </Button>
        </div>
        <Button
          variant="ghost"
          className="h-12 w-12 shrink-0 rounded-2xl text-destructive hover:bg-destructive/10"
          onClick={onRemove}
          aria-label="Xoá sản phẩm"
        >
          <Trash2 className="h-5 w-5" />
        </Button>
      </div>
    </div>
  );
}

src/components/shared/cart-order-summary.content:
"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { toast } from "sonner";
import { Button } from "@ui/components/button";
import { Input } from "@ui/components/input";
import { Label } from "@ui/components/label";
import { ArrowRight, Tag, TicketPercent } from "lucide-react";
import { useCart } from "@/hooks/use-cart";
import { formatVND } from "@/lib/format";
import { PROMO_CODE_EXAMPLES } from "@workspace/promo-codes";
import { cn } from "@ui/lib/utils";

type CartOrderSummaryProps = {
  /** Giỏ hàng: nút sang checkout. Thanh toán: chỉ bảng giá (nút đặt hàng ở card khác). */
  variant?: "cart-aside" | "checkout-total";
};

function PromoField({ className }: { className?: string }) {
  const {
    appliedPromoCode,
    applyPromo,
    clearPromo,
    subtotal,
    promoDiscount,
    promoLabel,
    promoError,
  } = useCart();
  const [draft, setDraft] = useState(appliedPromoCode ?? "");

  useEffect(() => {
    setDraft(appliedPromoCode ?? "");
  }, [appliedPromoCode]);

  const handleApply = (): void => {
    const r = applyPromo(draft);
    if (!r.ok) {
      toast.error(r.message);
      return;
    }
    toast.success(r.label);
    setDraft(r.normalizedCode);
  };

  const handleClear = (): void => {
    clearPromo();
    setDraft("");
    toast.message("Đã gỡ mã khuyến mãi");
  };

  return (
    <div className={cn("space-y-2", className)}>
      <Label
        htmlFor="cart-promo-code"
        className="flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-muted-foreground"
      >
        <TicketPercent className="size-3.5 text-primary" />
        Mã khuyến mãi
      </Label>
      <div className="flex gap-2">
        <Input
          id="cart-promo-code"
          value={draft}
          onChange={(e) => setDraft(e.target.value.toUpperCase())}
          placeholder="VD: GIAM50K"
          className="h-11 flex-1 rounded-xl border-outline-variant font-mono text-sm uppercase"
          disabled={subtotal <= 0}
          autoComplete="off"
        />
        <Button
          type="button"
          variant="secondary"
          className="h-11 shrink-0 rounded-xl px-4 font-bold"
          disabled={subtotal <= 0 || !draft.trim()}
          onClick={handleApply}
        >
          Áp dụng
        </Button>
      </div>
      <p className="text-[11px] leading-relaxed text-muted-foreground">
        Mã toàn đơn do kho cấu hình (đồng bộ từ máy chủ). Ví dụ:{" "}
        {PROMO_CODE_EXAMPLES.join(" · ")}. Giá KM theo{" "}
        <strong>từng sản phẩm / đơn vị</strong> (SL tối thiểu) tự cập nhật khi đổi số
        lượng — khác với ô mã bên dưới.
      </p>
      {appliedPromoCode && promoDiscount > 0 && promoLabel && (
        <div className="flex items-center justify-between rounded-xl border border-success/25 bg-success/5 px-3 py-2 text-sm">
          <span className="flex items-center gap-2 font-semibold text-success">
            <Tag className="size-4" />
            {promoLabel}
          </span>
          <Button
            type="button"
            variant="destructive"
            size="sm"
            className={"rounded-xl"}
            onClick={handleClear}
          >
            Gỡ mã
          </Button>
        </div>
      )}
      {promoError && (
        <p className="text-xs font-medium text-destructive">{promoError}</p>
      )}
    </div>
  );
}

export function CartOrderSummary({ variant = "cart-aside" }: CartOrderSummaryProps) {
  const { unitCount, subtotal, wholesaleSavings, promoDiscount, grandTotal } =
    useCart();

  return (
    <div
      className={cn(
        "space-y-5 border border-outline-variant bg-background p-6 shadow-sm",
        variant === "cart-aside" && "sticky top-24 rounded-3xl",
        variant === "checkout-total" && "rounded-2xl border-dashed",
      )}
    >
      <div className="space-y-1 border-b border-outline-variant/60 pb-4">
        <h2 className="text-lg font-extrabold tracking-tight text-foreground">
          Tổng đơn hàng
        </h2>
        <p className="text-xs text-muted-foreground">
          {unitCount} đơn vị trong giỏ — giá theo bảng giá ban đầu / khuyến mãi từng dòng.
        </p>
      </div>

      <PromoField />

      <dl className="space-y-3 text-sm">
        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Tạm tính</dt>
          <dd className="text-right font-bold tabular-nums">{formatVND(subtotal)}</dd>
        </div>
        {promoDiscount > 0 && (
          <div className="flex justify-between gap-4 text-primary">
            <dt className="font-medium">Giảm thêm (mã KM)</dt>
            <dd className="text-right font-bold tabular-nums">
              −{formatVND(promoDiscount)}
            </dd>
          </div>
        )}
        <div className="flex justify-between gap-4">
          <dt className="text-muted-foreground">Phí vận chuyển</dt>
          <dd className="text-right text-xs text-muted-foreground">
            Tính khi xác nhận đơn
          </dd>
        </div>
      </dl>
      {wholesaleSavings > 0 && (
        <div className="rounded-xl border border-success/20 bg-success/5 px-3 py-2.5 text-xs leading-relaxed text-success">
          <strong>Tiết kiệm từ giá khuyến mãi:</strong> so với giá ban đầu cùng quy cách, tạm tính đã
          thấp hơn{" "}
          <span className="font-black tabular-nums">
            {formatVND(wholesaleSavings)}
          </span>
          . Khoản này <em>không</em> trừ thêm lần nữa — chỉ để đối chiếu.
        </div>
      )}

      <div className="rounded-2xl bg-primary/5 px-4 py-3 ring-1 ring-primary/15">
        <div className="flex items-baseline justify-between gap-2">
          <span className="text-sm font-extrabold text-foreground">Thành tiền</span>
          <span className="text-2xl font-black tabular-nums tracking-tight text-primary">
            {formatVND(grandTotal)}
          </span>
        </div>
        <p className="mt-1 text-[11px] leading-relaxed text-muted-foreground">
          Thanh toán COD khi nhận hàng. Số tiền cuối khớp với đơn hàng sau khi hệ
          thống xác nhận tồn kho và mã KM.
        </p>
      </div>

      {variant === "cart-aside" && (
        <Button
          nativeButton={false}
          render={<Link href="/checkout" />}
          className="h-12 w-full rounded-xl text-base font-bold"
        >
          Tiến hành đặt hàng
          <ArrowRight className="ml-1 size-4" />
        </Button>
      )}
    </div>
  );
}

/** Khối nhập mã + gợi ý — dùng trong card tổng thanh toán checkout. */
export function CheckoutPromoField() {
  return (
    <div className="rounded-2xl border border-outline-variant/50 bg-muted/20 p-4">
      <PromoField />
    </div>
  );
}

src/components/shared/header.tsx.content:
"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  FileText,
  Home,
  Info,
  Mail,
  CircleHelp,
  Settings2,
  Type,
  ShoppingCart,
  Package,
  ShieldCheck,
  UserPlus,
  Store,
  ChevronDown,
  ExternalLink,
} from "lucide-react";
import { Badge } from "@ui/components/badge";
import { useCart } from "@/hooks/use-cart";
import { useOpenCartDrawer } from "@/components/shared/cart-drawer";
import { useSession } from "@/hooks/use-session";
import { Button, buttonVariants } from "@ui/components/button";
import {
  NavigationMenu,
  NavigationMenuItem,
  NavigationMenuList,
} from "@ui/components/navigation-menu";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu";
import { useTextSize } from "@ui/components/text-size-provider";
import { cn } from "@ui/lib/utils";
import { getAdminLoginUrl, getAdminRegisterUrl } from "@/features/auth/admin-bridge";
import { STORE_ENABLED } from "@/lib/store-feature";
import { Logo } from "../icons/logo";

const basePrimaryLinks = [
  {
    label: "Trang chủ",
    href: "/",
    icon: Home,
  },
  {
    label: "Cửa hàng",
    href: "/catalog",
    icon: ShoppingCart,
    storeOnly: true,
  },
  {
    label: "Bài viết",
    href: "/bai-viet",
    icon: FileText,
  },
] as const;

const primaryLinks = basePrimaryLinks.filter(
  (item) => STORE_ENABLED || !("storeOnly" in item && item.storeOnly),
);

const supportLinks = [
  {
    label: "Giới thiệu",
    href: "/ve-chung-toi",
    icon: Info,
    description: "Thông tin về tổ chức",
  },
  {
    label: "Liên hệ hỗ trợ",
    href: "/lien-he",
    icon: Mail,
    description: "Gửi yêu cầu hỗ trợ trực tiếp",
  },
  {
    label: "Trợ giúp",
    href: "/huong-dan-su-dung",
    icon: CircleHelp,
    description: "Hướng dẫn sử dụng",
  },
];

const isExactOrNestedPath = (pathname: string, href: string) => {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(`${href}/`);
};

/** Chỉ mount khi STORE_ENABLED — phải nằm trong CartDrawerHost. */
function HeaderStoreChrome({ pathname }: { pathname: string }) {
  const session = useSession();
  const { unitCount } = useCart();
  const openCart = useOpenCartDrawer();
  const isOrdersActive = isExactOrNestedPath(pathname, "/orders");

  return (
    <>
      {session ? (
        <Link
          href="/orders"
          className={cn(
            buttonVariants({
              variant: isOrdersActive ? "default" : "outline",
              size: "sm",
            }),
            "hidden sm:inline-flex"
          )}
        >
          <Package className="mr-1.5 size-4" />
          Đơn hàng
        </Link>
      ) : null}
      <Button
        type="button"
        variant="outline"
        size="icon"
        className="relative"
        onClick={openCart}
        aria-label={`Giỏ hàng${unitCount > 0 ? `, ${unitCount} món` : ""}`}
      >
        <ShoppingCart className="size-4" />
        {unitCount > 0 ? (
          <Badge className="absolute -right-1 -top-1 flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[9px]">
            {unitCount > 99 ? "99+" : unitCount}
          </Badge>
        ) : null}
      </Button>
    </>
  );
}

const TEXT_SIZE_OPTIONS = [
  { value: "sm", label: "Nhỏ", sampleClass: "text-[11px]" },
  { value: "base", label: "Vừa", sampleClass: "text-sm" },
  { value: "lg", label: "Lớn", sampleClass: "text-base" },
] as const;

type TextSizeValue = (typeof TEXT_SIZE_OPTIONS)[number]["value"];

function HeaderOptionsMenu({
  size,
  setSize,
  adminLoginUrl,
  adminRegisterUrl,
  isLoginActive,
  isRegisterActive,
}: {
  size: TextSizeValue;
  setSize: (value: TextSizeValue) => void;
  adminLoginUrl: string;
  adminRegisterUrl: string;
  isLoginActive: boolean;
  isRegisterActive: boolean;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            className={cn(
              "group/settings inline-flex h-9 shrink-0 cursor-pointer items-stretch overflow-hidden rounded-xl border border-border/80 bg-card text-left shadow-sm outline-none transition-all duration-200",
              "hover:-translate-y-px hover:border-primary/35 hover:shadow-md",
              "focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
              "data-popup-open:border-primary/45 data-popup-open:bg-primary/[0.04] data-popup-open:shadow-md data-popup-open:ring-2 data-popup-open:ring-primary/15"
            )}
            aria-label="Mở tùy chọn hiển thị và tài khoản"
          />
        }
      >
        <span className="relative flex w-9 shrink-0 items-center justify-center bg-gradient-to-br from-primary via-primary to-primary/80 text-primary-foreground">
          <span
            className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(255,255,255,0.28),transparent_55%)]"
            aria-hidden
          />
          <Settings2 className="relative size-4" aria-hidden />
        </span>
        <span className="hidden min-w-[5.5rem] items-center justify-between gap-2 border-l border-border/70 px-3 sm:flex">
          <span className="flex flex-col leading-none">
            <span className="text-sm font-semibold text-foreground">Cài đặt</span>
            <span className="mt-0.5 text-[10px] font-medium text-muted-foreground">
              Hiển thị · Tài khoản
            </span>
          </span>
          <ChevronDown
            className="size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-data-popup-open/settings:rotate-180"
            aria-hidden
          />
        </span>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        sideOffset={8}
        className="w-[min(100vw-1.5rem,20rem)] overflow-hidden rounded-xl p-0 shadow-lg ring-1 ring-border/60"
      >
        <div className="border-b border-border/60 bg-gradient-to-r from-primary/10 via-primary/5 to-transparent px-4 py-3">
          <p className="text-sm font-semibold text-foreground">Tùy chọn</p>
          <p className="text-xs text-muted-foreground">
            Cỡ chữ và truy cập hệ thống
          </p>
        </div>

        <div className="space-y-4 p-3">
          <section className="rounded-lg border border-border/60 bg-muted/20 p-3">
            <div className="mb-3 flex items-center gap-2">
              <span className="flex size-8 items-center justify-center rounded-lg border border-border/70 bg-background text-primary">
                <Type className="size-4" aria-hidden />
              </span>
              <div>
                <p className="text-sm font-semibold text-foreground">Cỡ chữ</p>
                <p className="text-xs text-muted-foreground">
                  Chọn kích thước dễ đọc
                </p>
              </div>
            </div>
            <div
              role="radiogroup"
              aria-label="Cỡ chữ"
              className="grid grid-cols-3 gap-2"
            >
              {TEXT_SIZE_OPTIONS.map((option) => {
                const isActive = size === option.value;

                return (
                  <button
                    key={option.value}
                    type="button"
                    role="radio"
                    aria-checked={isActive}
                    onClick={() => setSize(option.value)}
                    className={cn(
                      "flex flex-col items-center gap-1 rounded-lg border px-2 py-2.5 transition-all",
                      isActive
                        ? "border-primary bg-primary text-primary-foreground shadow-sm"
                        : "border-border/70 bg-background text-foreground hover:border-primary/30 hover:bg-primary/5"
                    )}
                  >
                    <span
                      className={cn(
                        "font-bold leading-none",
                        option.sampleClass,
                        isActive ? "text-primary-foreground" : "text-foreground"
                      )}
                    >
                      Aa
                    </span>
                    <span className="text-[10px] font-medium uppercase tracking-wide opacity-90">
                      {option.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </section>

          <section>
            <p className="mb-2 px-1 text-xs font-semibold text-muted-foreground">
              Tài khoản
            </p>
            <div className="space-y-1.5">
              {STORE_ENABLED ? (
                <HeaderStoreAccountMenuItem isLoginActive={isLoginActive} />
              ) : null}
              <HeaderAccountLink
                label="Cổng quản trị"
                description="Đăng nhập khu vực quản trị"
                icon={ShieldCheck}
                href={adminLoginUrl}
                external
              />
              <HeaderAccountLink
                label="Đăng ký quản trị"
                description="Tạo tài khoản quản trị mới"
                icon={UserPlus}
                href={adminRegisterUrl}
                external
                active={isRegisterActive}
              />
            </div>
          </section>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function HeaderAccountLink({
  label,
  description,
  icon: Icon,
  href,
  external = false,
  active = false,
  onClick,
}: {
  label: string;
  description: string;
  icon: typeof ShieldCheck;
  href?: string;
  external?: boolean;
  active?: boolean;
  onClick?: () => void;
}) {
  const content = (
    <>
      <span
        className={cn(
          "flex size-9 shrink-0 items-center justify-center rounded-lg border",
          active
            ? "border-primary/30 bg-primary/10 text-primary"
            : "border-border/70 bg-background text-muted-foreground"
        )}
      >
        <Icon className="size-4" aria-hidden />
      </span>
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-1.5 text-sm font-medium text-foreground">
          {label}
          {external ? <ExternalLink className="size-3 text-muted-foreground" /> : null}
        </span>
        <span className="block text-xs text-muted-foreground">{description}</span>
      </span>
    </>
  );

  const className = cn(
    "flex w-full items-center gap-3 rounded-lg border border-transparent px-2 py-2 text-left transition-colors",
    active ? "bg-primary/5" : "hover:border-border/60 hover:bg-muted/40"
  );

  if (onClick) {
    return (
      <button type="button" onClick={onClick} className={className}>
        {content}
      </button>
    );
  }

  return (
    <a
      href={href}
      className={className}
      {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
    >
      {content}
    </a>
  );
}

function HeaderStoreAccountMenuItem({
  isLoginActive,
}: {
  isLoginActive: boolean;
}) {
  const session = useSession();

  return (
    <HeaderAccountLink
      label={session ? "Hồ sơ cửa hàng" : "Đăng nhập cửa hàng"}
      description={
        session ? "Quản lý thông tin đại lý" : "Truy cập tài khoản cửa hàng"
      }
      icon={Store}
      active={isLoginActive}
      onClick={() => {
        window.location.assign(session ? "/profile" : "/login");
      }}
    />
  );
}

export function Header() {
  const pathname = usePathname();
  const { size, setSize } = useTextSize();
  const adminLoginUrl = getAdminLoginUrl();
  const adminRegisterUrl = getAdminRegisterUrl();
  const isSupportActive = supportLinks.some((link) => isExactOrNestedPath(pathname, link.href));
  const isLoginActive = isExactOrNestedPath(pathname, "/login");
  const isRegisterActive = isExactOrNestedPath(pathname, "/register");

  return (
    <header className="sticky top-0 z-50 w-full border-b border-border/70 bg-background/95 backdrop-blur">
      <div className="mx-auto flex h-16 w-full max-w-[1440px] items-center justify-between gap-3 px-6 md:px-12">
        <div className="flex w-full items-center justify-start gap-3">
          <Link href="/" className="flex shrink-0 items-center gap-2">
            <Logo className="h-8 w-8 sm:h-10 sm:w-10" />
            <div className="hidden leading-tight sm:block">
              <div className="text-xs font-semibold">Trường Đại học Ngân hàng</div>
              <div className="text-[11px] text-muted-foreground">Thành Phố Hồ Chí Minh</div>
            </div>
          </Link>

          <NavigationMenu className="hidden md:flex">
            <NavigationMenuList className="gap-1">
              {primaryLinks.map((item) => {
                const isActive = isExactOrNestedPath(pathname, item.href);

                return (
                  <NavigationMenuItem key={item.href}>
                    <Link
                      href={item.href}
                      prefetch={item.href === "/bai-viet" ? false : undefined}
                      aria-current={isActive ? "page" : undefined}
                      className={cn(
                        "inline-flex items-center gap-1.5 rounded-md px-3 py-2 text-sm font-semibold transition-colors",
                        isActive
                          ? "bg-primary text-primary-foreground shadow-sm"
                          : "text-muted-foreground hover:bg-muted hover:text-foreground"
                      )}
                    >
                      <item.icon className="size-4" />
                      {item.label}
                    </Link>
                  </NavigationMenuItem>
                );
              })}

              <NavigationMenuItem>
                <DropdownMenu>
                  <DropdownMenuTrigger
                    render={
                      <button
                        className={cn(
                          "inline-flex items-center rounded-md px-3 py-2 text-sm font-semibold transition-colors",
                          isSupportActive
                            ? "bg-primary text-primary-foreground shadow-sm"
                            : "text-foreground hover:bg-muted/80"
                        )}
                      />
                    }
                  >
                    Hỗ trợ
                  </DropdownMenuTrigger>
                  <DropdownMenuContent className="w-[360px] p-2">
                    <div className="grid grid-cols-2 gap-2">
                      {supportLinks.map((item) => {
                        const isActive = isExactOrNestedPath(pathname, item.href);

                        return (
                          <DropdownMenuItem key={item.href} className="p-0">
                            <Link
                              href={item.href}
                              aria-current={isActive ? "page" : undefined}
                              className={cn(
                                "flex w-full items-start gap-2 rounded-md px-2 py-2 transition-colors",
                                isActive ? "bg-muted" : "hover:bg-muted/70"
                              )}
                            >
                              <span
                                className={cn(
                                  "rounded-md border p-1.5",
                                  isActive
                                    ? "border-primary/30 bg-primary/10 text-primary"
                                    : "border-border"
                                )}
                              >
                                <item.icon className="size-4" />
                              </span>
                              <span className="min-w-0">
                                <span className="block text-sm font-medium">{item.label}</span>
                                <span className="block text-xs text-muted-foreground">
                                  {item.description}
                                </span>
                              </span>
                            </Link>
                          </DropdownMenuItem>
                        );
                      })}
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
              </NavigationMenuItem>
            </NavigationMenuList>
          </NavigationMenu>
        </div>

        <div className="flex shrink-0 items-center gap-2">
          {STORE_ENABLED ? <HeaderStoreChrome pathname={pathname} /> : null}
          <HeaderOptionsMenu
            size={size}
            setSize={setSize}
            adminLoginUrl={adminLoginUrl}
            adminRegisterUrl={adminRegisterUrl}
            isLoginActive={isLoginActive}
            isRegisterActive={isRegisterActive}
          />
        </div>
      </div>
    </header>
  );
}

