      >
        <div className="flex items-center justify-between gap-4 border-b pb-6">
          <div className="space-y-1">
            <Heading as="h2" size="section">
              Tin tức và sự kiện
            </Heading>
            <Text variant="muted">Cập nhật nhanh các thông tin mới từ nhà trường</Text>
